// The browser engine must reproduce the Python engine exactly.
// Fixture is generated by: python scripts/export_fixtures.py
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { backtest, sweep, walkForward, mulberry32 } from "../src/engine/analysis.js";
import { parseCsv, dateKey } from "../src/engine/csv.js";
import { STRATEGIES } from "../src/engine/strategies.js";

const fx = JSON.parse(readFileSync(new URL("./fixtures/parity.json", import.meta.url)));
const markets = JSON.parse(readFileSync(new URL("../public/data/markets.json", import.meta.url)));
const slice = (mk) => Object.fromEntries(Object.entries(markets[mk].data).map(([k, v]) => [k, v.slice(0, fx.bars)]));

const TOL = 1e-9;
function close(a, b, path) {
  if (a === null || b === null) return assert.equal(a, b, path);
  if (typeof a === "number") {
    const scale = Math.max(1, Math.abs(b));
    assert.ok(Math.abs(a - b) <= TOL * scale, `${path}: js ${a} vs py ${b}`);
    return;
  }
  if (Array.isArray(a)) {
    assert.equal(a.length, b.length, `${path} length`);
    a.forEach((v, i) => close(v, b[i], `${path}[${i}]`));
    return;
  }
  if (typeof a === "object") {
    for (const k of Object.keys(b)) close(a[k], b[k], `${path}.${k}`);
    return;
  }
  assert.equal(a, b, path);
}

test(`backtests match Python across ${fx.cases.length} market × strategy × config cases`, () => {
  for (const c of fx.cases) {
    const r = backtest(slice(c.market), c.strategy, {}, c.config, 200);
    const tag = `${c.market}/${c.strategy}/short=${c.config.allow_short}`;
    close(r.position, c.position, `${tag} position`);
    close(r.equity, c.equity, `${tag} equity`);
    assert.equal(r.trades.length, c.trades.length, `${tag} trade count`);
    close(r.trades, c.trades, `${tag} trades`);
    close(r.metrics, c.metrics, `${tag} metrics`);
    if (c.monte_carlo) close(r.monte_carlo, c.monte_carlo, `${tag} monte carlo`);
    else assert.equal(r.monte_carlo, null);
  }
});

test("parameter sweep matches Python", () => {
  const s = sweep(slice("volatile"), "donchian", {}, { stop_loss_pct: 6, fee_bps: 5, slippage_bps: 5, allow_short: false, initial_capital: 100000, periods_per_year: 252 });
  close(s.x.values, fx.sweep.x.values, "x");
  close(s.y.values, fx.sweep.y.values, "y");
  close(s.cells, fx.sweep.cells, "cells");
});

test("walk-forward matches Python", () => {
  const w = walkForward(slice("volatile"), "sma_cross", {}, { fee_bps: 5, slippage_bps: 5, stop_loss_pct: 0, allow_short: false, initial_capital: 100000, periods_per_year: 252 }, 4);
  close(w.folds, fx.walk_forward.folds, "folds");
  close(w.oos_equity, fx.walk_forward.oos_equity, "oos equity");
  close(w.efficiency, fx.walk_forward.efficiency, "efficiency");
});

test("strategy catalogue (names, parameter ranges, defaults) matches Python", () => {
  assert.deepEqual(STRATEGIES, fx.strategies);
});

test("PRNG matches the Python implementation", () => {
  const r = mulberry32(42);
  assert.deepEqual([r(), r(), r()].map((x) => x.toFixed(10)), ["0.6011037519", "0.4482905590", "0.8524657935"]);
});

test("CSV parser handles NSE-style newest-first files with quoted numbers", () => {
  const rows = ['Date ,OPEN ,HIGH ,LOW ,PREV. CLOSE ,ltp ,close ,VOLUME '];
  for (let i = 40; i >= 1; i--) {
    const d = new Date(Date.UTC(2024, 0, i));
    const mon = d.toLocaleString("en", { month: "short", timeZone: "UTC" });
    rows.push(`${String(i).padStart(2, "0")}-${mon}-2024,"1,${100 + i}.00","1,${102 + i}.00","1,${99 + i}.00",0,1,"1,${101 + i}.50","12,345"`);
  }
  const d = parseCsv(rows.join("\n"));
  assert.equal(d.close.length, 40);
  assert.equal(d.date[0], "01-Jan-2024");
  assert.equal(d.close[0], 1102.5); // picked "close", not "ltp"
  assert.equal(d.volume[0], 12345);
  assert.equal(dateKey("31-12-2024"), "2024-12-31");
  assert.throws(() => parseCsv("a,b\n1,2\n3,4"), /missing/);
});

import { runSession } from "../src/live/engine.js";
import { intradayCharges } from "../src/live/costs.js";

test("live pipeline: full simulated day gives the same candles, signals, fills and trades as Python", () => {
  const session = JSON.parse(readFileSync(new URL("../public/data/session.json", import.meta.url)));
  const { events } = runSession(session);
  assert.equal(events.length, fx.live_events.length, "event count");
  close(events, fx.live_events, "live");
});

test("intraday charges match the Python cost model", () => {
  assert.deepEqual(intradayCharges(100000, 101000), { brokerage: 40, stt: 25.25, transaction: 6.17, sebi: 0.2, ipft: 0, gst: 8.35, stamp: 3, total: 82.97 });
});
